script:
frappe.ui.form.on('Workspace', {
    refresh: function(frm) {
        // If the user clicks 'Items List', jump to the real Item List
        if (frm.doc.name == "Items List") {
            frappe.set_route("List", "Item");
        }
        // If the user clicks 'Customers', jump to real Customer List
        if (frm.doc.name == "Customers") {
            frappe.set_route("List", "Customer");
        }
        // Add more 'if' blocks here for Sales Invoices, Suppliers, etc.
    }
});

frappe.ui.form.on('Item', {
    refresh(frm) {
        calculate_margin_amount(frm);
    },
    last_purchase_rate(frm) {
        calculate_margin_amount(frm);
    },
    standard_rate(frm) {
        calculate_margin_amount(frm);
    }
});

function calculate_margin_amount(frm) {
    let purchase_rate = flt(frm.doc.last_purchase_rate);
    let sell_rate = flt(frm.doc.standard_rate);
    frm.set_value('custom_margin', sell_rate - purchase_rate);
}

frappe.ui.form.on("Sales Invoice Item", {

    barcode_scan: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.barcode_scan) return;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Item Barcode",
                filters: {
                    barcode: row.barcode_scan
                },
                fields: ["parent", "uom"]
            },

            callback: function(r) {

                if (r.message && r.message.length) {

                    let d = r.message[0];

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "item_code",
                        d.parent
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "uom",
                        d.uom
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "qty",
                        1
                    );

                    frm.refresh_field("items");
                }
            }
        });
    }
});

frappe.ui.form.on('Sales Invoice Item', {
	refresh(frm) {
		// your code here
	}
})

frappe.ui.form.on('Sales Invoice Item', {
	refresh(frm) {
		// your code here
	}
})

frappe.ui.form.on('Item', {
    refresh(frm) {
        calculate_child_rates(frm);
    },
    last_purchase_rate(frm) {
        calculate_child_rates(frm);
    }
});

frappe.ui.form.on('Retail Packing Detail', {
    conversion_factor(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        let base_rate = flt(frm.doc.last_purchase_rate);
        let calculated_rate = base_rate * flt(row.conversion_factor || 1);
        frappe.model.set_value(cdt, cdn, 'purchase_rate', calculated_rate);
    },

    custom_retail_packing_detail_add(frm, cdt, cdn) {
        let base_rate = flt(frm.doc.last_purchase_rate);
        frappe.model.set_value(cdt, cdn, 'purchase_rate', base_rate);
    }
});

function calculate_child_rates(frm) {
    let base_rate = flt(frm.doc.last_purchase_rate);
    $.each(frm.doc.custom_retail_packing_detail || [], function(i, row) {
        let calculated_rate = base_rate * flt(row.conversion_factor || 1);
        frappe.model.set_value(row.doctype, row.name, 'purchase_rate', calculated_rate);
    });
}

frappe.ui.form.on('Item', {

    custom_scale_item: function(frm) {

        if (frm.doc.custom_scale_item) {

            if (!frm.doc.custom_barcode) {

                let prefix = "21";
                let rand = Math.floor(10000 + Math.random() * 90000);

                frm.set_value(
                    'custom_barcode',
                    prefix + rand
                );
            }
        }
    }

});

frappe.ui.form.on('Item', {
    refresh(frm) {
        calculate_margins(frm);
    },
    last_purchase_rate(frm) {
        calculate_margins(frm);
    },
    standard_rate(frm) {
        calculate_margins(frm);
    }
});

function calculate_margins(frm) {
    let purchase_rate = flt(frm.doc.last_purchase_rate);
    let sell_rate = flt(frm.doc.standard_rate);
    let margin_amt = sell_rate - purchase_rate;

    frm.set_value('custom_margin', margin_amt);
    frm.set_value('custom_margin_', sell_rate > 0 ? (margin_amt / sell_rate) * 100 : 0);
}

frappe.ui.form.on('Item', {
    custom_warranty: function(frm) {
        if (!frm.doc.custom_warranty) {
            frm.set_value('custom_in_months', null);
        }
    }
});

frappe.ui.form.on("Item", {
    validate(frm) {
        remove_empty_barcode_rows(frm);
    },
    before_save(frm) {
        remove_empty_barcode_rows(frm);
    }
});

function remove_empty_barcode_rows(frm) {
    if (!Array.isArray(frm.doc.barcodes) || !frm.doc.barcodes.length) return;

    let removed = false;
    for (let i = frm.doc.barcodes.length - 1; i >= 0; i--) {
        const row = frm.doc.barcodes[i];
        if (row.barcode) continue;

        if (row.doctype && row.name) {
            frappe.model.clear_doc(row.doctype, row.name);
        }
        frm.doc.barcodes.splice(i, 1);
        removed = true;
    }

    if (removed) {
        frm.refresh_field("barcodes");
    }
}

frappe.ui.form.on("Item", {
    item_name(frm) {
        set_last_purchase_rate_from_same_item_name(frm);
    },

    refresh(frm) {
        if (frm.is_new() && frm.doc.item_name && !flt(frm.doc.last_purchase_rate)) {
            set_last_purchase_rate_from_same_item_name(frm);
        }
    }
});

function set_last_purchase_rate_from_same_item_name(frm) {
    if (!frm.is_new() || !frm.doc.item_name || flt(frm.doc.last_purchase_rate)) {
        return;
    }

    frappe.db.get_list("Item", {
        fields: ["name", "last_purchase_rate", "standard_rate"],
        filters: {
            item_name: frm.doc.item_name,
            disabled: 0
        },
        order_by: "modified desc",
        limit: 1
    }).then((items) => {
        if (!items.length || !flt(items[0].last_purchase_rate)) {
            return;
        }

        frm.set_value("last_purchase_rate", items[0].last_purchase_rate);
        frm.dashboard.set_headline(__("Last purchase rate fetched from existing Item {0}", [items[0].name]));
    });
}
